#include <string>
int main(){const auto parsed=nadir::astro::parse_rinex_observation_epochs("     3.04           O                   RINEX VERSION / TYPE\n                                                            END OF HEADER\n> 2026 01 01 00 00 00.0000000  0  2\nG01  123.0\nG02  456.0\n");if(!parsed.ok||!parsed.epochs||parsed.epochs->size()!=1||(*parsed.epochs)[0].satellite_count!=2||(*parsed.epochs)[0].epoch!="2026-01-01T00:00:00.000")return 1;if(nadir::astro::parse_rinex_observation_epochs("     3.04           O                   RINEX VERSION / TYPE\n                                                            END OF HEADER\n> 2026 13 01 00 00 00 0 1\n").ok)return 2;return nadir::astro::parse_rinex_observation_epochs(std::string(16U*1024U*1024U+1U,'x')).ok?3:0;}
